<article class="card printable"><div class="card-body p-4"><div class="d-flex justify-content-between"><h1 class="h3">ISHEP Payment Receipt</h1><button class="btn btn-outline-secondary no-print" onclick="window.print()">Print</button></div><p class="lead"><?=e($payment['payment_reference'])?></p><dl class="row"><dt class="col-4">Member</dt><dd class="col-8"><?=e($payment['member_name'])?></dd><dt class="col-4">Amount</dt><dd class="col-8"><?=e($payment['currency'].' '.$payment['amount'])?></dd><dt class="col-4">Method</dt><dd class="col-8"><?=e(str_replace('_',' ',$payment['payment_method']))?></dd><dt class="col-4">Manual reference</dt><dd class="col-8"><?=e($payment['manual_reference'])?></dd><dt class="col-4">Received</dt><dd class="col-8"><?=e($payment['received_at'])?></dd><dt class="col-4">Status</dt><dd class="col-8"><?=e($payment['status'])?></dd></dl><div class="alert alert-info">This receipt confirms an ISHEP manual record. It is not confirmation from a bank, card network, or online payment gateway.</div></div></article>
